#include "editor.hpp"
namespace touch::ui {
void Editor::canvas_input(const CanvasHit& hit,bool hovered){auto& io=ImGui::GetIO();auto mouse=io.MousePos;if(transform&&modal_transform)return;
if(hovered&&ImGui::IsMouseClicked(0)&&!ImGui::IsKeyDown(ImGuiKey_Space)&&!wire){if(box_select){box_start=mouse;box_dragging=true;box_extend|=io.KeyShift;return;}
if(hit.output||hit.input){Endpoint endpoint=hit.output?Endpoint{*hit.output,true}:Endpoint{*hit.input,false};wire_before=document.graph;wire_original.reset();wire_start=mouse;if(!endpoint.output){auto it=std::find_if(document.graph.edges.begin(),document.graph.edges.end(),[&](auto e){return e.to==endpoint.port;});if(it!=document.graph.edges.end()){wire_original=*it;endpoint={it->from,true};}}wire=endpoint;}
else if(hit.node){active_node=*hit.node;if(io.KeyShift){if(!document.selected.erase(*hit.node))document.selected.insert(*hit.node);}else{if(!document.selected.contains(*hit.node))document.selected.clear();document.selected.insert(*hit.node);begin_transform(1);}}
else if(!io.KeyShift)document.selected.clear();}
if(wire&&ImGui::IsMouseReleased(0)){if(!hovered){cancel_wire();return;}if(std::hypot(mouse.x-wire_start.x,mouse.y-wire_start.y)<=4&&((hit.output&&wire->output&&*hit.output==wire->port)||(hit.input&&wire_original&&*hit.input==wire_original->to)||(hit.input&&!wire->output&&*hit.input==wire->port)))return;
std::optional<Endpoint> target;if(hit.input)target=Endpoint{*hit.input,false};else if(hit.output)target=Endpoint{*hit.output,true};else if(hit.node&&*hit.node!=wire->port.node){if(auto n=document.graph.find(*hit.node))if(auto d=services.registry.find(n->type)){auto signal=port_signal(document.graph,services.registry,wire->port,wire->output);if(auto index=compatible_port(*d,signal,!wire->output))target=Endpoint{{*hit.node,*index},!wire->output};}}
if(target){connect_endpoints(*wire,*target);wire.reset();if(!conversion){wire_before.reset();wire_original.reset();}}
else if(!hit.node&&!hit.input&&!hit.output){if(wire_original){auto original=*wire_original;document.edit([&](Graph& g){std::erase(g.edges,original);});changed();cancel_wire();}else{pending_wire=wire;wire.reset();ImGui::OpenPopup("Operators");}}
else{status="Choose a compatible socket";cancel_wire();}}
}
void Editor::canvas_menu(const CanvasHit& hit,bool hovered){auto& io=ImGui::GetIO();palette();if(transform&&modal_transform){if(ImGui::IsMouseClicked(1))finish_transform(true);return;}if(wire&&ImGui::IsMouseClicked(1)){cancel_wire();return;}wire_stroke(hit);if(hovered&&(io.KeyCtrl||io.KeyShift)&&ImGui::IsMouseDown(1))return;
if(hovered&&ImGui::IsMouseClicked(1)){context_edge=hit.edge;context_node=hit.node;if(hit.node&&!document.selected.contains(*hit.node))document.selected={*hit.node};ImGui::OpenPopup("Canvas actions");}
if(ImGui::BeginPopup("Canvas actions")){if(context_node){if(ImGui::MenuItem("Move          G")){begin_transform(1,true);ImGui::CloseCurrentPopup();}if(ImGui::MenuItem("Scale         S")){begin_transform(2,true);ImGui::CloseCurrentPopup();}if(ImGui::MenuItem("Rotate        R")){begin_transform(3,true);ImGui::CloseCurrentPopup();}if(ImGui::MenuItem("Duplicate  Sh+D"))duplicate_selection();if(ImGui::MenuItem("Frame selection"))fit(true);if(ImGui::MenuItem("Delete        X")){document.erase();changed();}if(ImGui::MenuItem("Delete and reconnect")){try{document.edit([&](Graph& g){erase_and_reconnect(g,document.selected,services.registry);});document.selected.clear();changed();}catch(const std::exception& e){status=e.what();}}}
else if(context_edge){auto edge=*context_edge;if(ImGui::MenuItem("Insert reroute"))insert_reroute(edge,world(ImGui::GetIO().MousePos));if(ImGui::MenuItem("Cut link")){document.edit([&](Graph& g){std::erase(g.edges,edge);});changed();}if(document.selected.size()==1&&ImGui::MenuItem("Insert selected node")){try{document.edit([&](Graph& g){insert_on_edge(g,edge,*document.selected.begin(),services.registry);});changed();}catch(const std::exception& e){status=e.what();}}}
else {if(ImGui::MenuItem("Add operator"))ImGui::OpenPopup("Operators");palette();if(ImGui::MenuItem("Frame all"))fit();if(ImGui::MenuItem("Select all"))for(auto& n:document.graph.nodes)document.selected.insert(n.id);}
ImGui::EndPopup();}}
}
